def table(headers,rows,widths=None):
 t=doc.add_table(rows=1,cols=len(headers));t.autofit=False
 bidi=OxmlElement('w:bidiVisual');bidi.set(qn('w:val'),'1');t._tbl.tblPr.append(bidi)
 if widths:
  for c,w in zip(t.columns,widths):c.width=Inches(w)
 for i,x in enumerate(headers):t.rows[0].cells[i].text=x
 for row in rows:
  for cell,x in zip(t.add_row().cells,row):cell.text=str(x)
 for ri,row in enumerate(t.rows):
  for ci,c in enumerate(row.cells):
   if widths:c.width=Inches(widths[ci])
   pr=c._tc.get_or_add_tcPr();b=OxmlElement('w:tcBorders')
   for edge in ['top','left','bottom','right']:
    e=OxmlElement('w:'+edge);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4');e.set(qn('w:color'),'D9D9D9');b.append(e)
   pr.append(b);sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'DCE6F1' if ri==0 else 'F4F6F8' if ri%2==0 else 'FFFFFF');pr.append(sh)
   for para in c.paragraphs:
    rtl(para);para.paragraph_format.space_after=Pt(5);para.paragraph_format.space_before=Pt(5)
    for run in para.runs:run.font.size=Pt(10.5);run.bold=ri==0
 repeat=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(repeat)
 return t
